"""Shared visual theme and Plotly runtime for both research reports."""

import html
import json

from plotly.utils import PlotlyJSONEncoder

CSS = '\n:root{--ink:#203343;--muted:#627786;--teal:#147d92;--paper:#f4f6f7;--line:#dce4e8}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:75px}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 Arial,sans-serif}header{background:#172e3d;color:white;padding:68px max(6vw,24px) 52px}header h1{font-size:clamp(36px,5.4vw,68px);line-height:1.06;letter-spacing:-2px;max-width:1000px;margin:20px 0}header h1 span{color:#78cccd}.eyebrow{font-size:11px;letter-spacing:2px;font-weight:700;color:var(--teal)}header .eyebrow{color:#87cdd4}.lede{font-size:20px;max-width:800px;line-height:1.5}.meta{font-size:12px;color:#b9ced8;margin-top:25px}nav{position:sticky;top:0;z-index:20;background:#fffffff5;border-bottom:1px solid var(--line);padding:14px max(5vw,20px);display:flex;gap:24px;overflow:auto;white-space:nowrap;backdrop-filter:blur(8px)}nav a{font-size:13px;font-weight:600;color:var(--ink);text-decoration:none}a{color:var(--teal)}main{max-width:1440px;margin:auto;padding:0 32px}section{padding:52px 0;border-bottom:1px solid var(--line)}h2{font-size:31px;letter-spacing:-.7px;line-height:1.25;margin:12px 0 20px}h3{font-size:18px;line-height:1.35}p{max-width:1100px;margin:16px 0}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:28px 0}.kpis>div{background:white;border-top:3px solid var(--teal);padding:24px}.kpis strong{display:block;font-size:35px;line-height:1.15}.kpis span{display:block;font-size:12px;color:var(--muted);margin-top:10px}.insights{display:grid;grid-template-columns:repeat(2,1fr);gap:20px}.insights article{border:1px solid var(--line);padding:20px 24px;background:white}.insights h3{margin:0 0 10px}.insights p{margin:0;font-size:14px}.two-col{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.chart{background:white;border:1px solid var(--line);border-radius:6px;margin:22px 0;min-height:420px;overflow:hidden}.chart.failed{padding:20px;color:#a0342a}.controls{display:flex;align-items:center;gap:20px;flex-wrap:wrap;background:#e8eff2;padding:15px 20px;border-radius:4px;margin:25px 0 0}.controls label{font-size:12px;font-weight:700;display:flex;align-items:center;gap:8px}.controls span{font-size:12px;color:var(--muted)}select{font:14px Arial,sans-serif;padding:9px 12px;max-width:420px;background:white;color:var(--ink);border:1px solid #aebfc9;border-radius:4px}aside{border-left:4px solid var(--teal);background:#e6f0f1;padding:18px 22px;margin:26px 0;font-size:14px;max-width:1100px}.caption{font-size:12px;color:var(--muted)}.table-scroll{overflow:auto;border:1px solid var(--line);background:white;max-height:500px;margin:18px 0}.data-table{border-collapse:collapse;width:100%;font-size:12px;line-height:1.5}.data-table th{background:#eaf0f3;position:sticky;top:0;font-weight:600;text-align:left;white-space:nowrap}.data-table td,.data-table th{padding:10px 12px;border-bottom:1px solid var(--line)}.data-table tr:nth-child(even){background:#fafcfd}.links{display:flex;flex-wrap:wrap;gap:14px;margin:18px 0}.download{font-size:12px;border-bottom:1px solid #9bbbc5;text-decoration:none;padding-bottom:3px}details{margin:20px 0}summary{font-size:14px;font-weight:700;cursor:pointer}li{margin:12px 0;max-width:1000px}code{background:#e4ebee;padding:4px 7px;border-radius:3px;font-size:13px}.sources{font-size:12px;color:var(--muted)}footer{padding:28px 32px;text-align:center;font-size:10px;letter-spacing:1.5px;color:var(--muted)}@media(max-width:900px){main{padding:0 18px}.two-col,.insights{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(2,1fr)}header{padding-top:40px}nav{gap:18px}h2{font-size:27px}.controls label{flex-wrap:wrap}select{max-width:100%;font-size:12px}.chart{overflow:auto}}\n\n.report-switch{display:flex;gap:12px;margin-top:24px;flex-wrap:wrap}.report-switch a{color:#bddce4;border:1px solid #4a697b;border-radius:4px;padding:7px 14px;text-decoration:none;font-size:12px}.report-switch a[aria-current="page"]{background:#e5f3f5;color:#172e3d;border-color:#e5f3f5}.verdict{background:white;border:1px solid var(--line);padding:22px 26px;margin:26px 0}.verdict strong{color:var(--teal)}.decision-table td:first-child{font-weight:700}.status{font-size:11px;font-weight:700;padding:4px 8px;background:#e6f0f1;border-radius:3px}.dataset-label{font-size:12px;color:var(--muted)}nav a[aria-current="page"]{color:var(--teal)}.chart{min-width:0}.data-table th{white-space:normal;min-width:80px}.table-scroll .data-table td{vertical-align:top}.insights article p a{white-space:nowrap}\n'

RUNTIME = "\nconst report=JSON.parse(document.getElementById('report-data').textContent);\nconst config={responsive:true,displaylogo:false,toImageButtonOptions:{format:'png',scale:2},scrollZoom:false};\nfunction specification(el){return el.dataset.bank?report.banks[el.dataset.bank][el.dataset.selection]:report.figures[el.dataset.figure];}\nasync function draw(el){const spec=specification(el);if(!spec)return;try{el.style.minHeight=spec.layout.height+'px';await Plotly.react(el,spec.data,spec.layout,config);el.dataset.rendered='true';}catch(e){el.classList.add('failed');el.textContent='Chart failed: '+e.message;console.error(e);}}\nconst observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){draw(entry.target);observer.unobserve(entry.target);}}),{rootMargin:'250px'});\ndocument.querySelectorAll('.chart').forEach(el=>{const spec=specification(el);if(spec)el.style.minHeight=spec.layout.height+'px';observer.observe(el);});\nfunction bind(id,handler){const element=document.getElementById(id);if(element)element.addEventListener('change',handler);}\nbind('currency-select',e=>{const el=document.getElementById('currency-chart');el.dataset.selection=e.target.value;draw(el);});\nfunction updateSignal(){const el=document.getElementById('signal-chart');el.dataset.selection=['signal-horizon','signal-window','signal-method'].map(id=>document.getElementById(id).value).join('|');draw(el);}\n['signal-horizon','signal-window','signal-method'].forEach(id=>bind(id,updateSignal));\nbind('baseline-horizon',e=>{const el=document.getElementById('baseline-chart');el.dataset.selection=e.target.value;draw(el);});\nbind('quality-component',e=>{const el=document.getElementById('availability-map');el.dataset.selection=e.target.value;draw(el);});\n"

def render_document(title, content, figures, banks, plotly_js):
    payload=json.dumps({"figures":figures,"banks":banks},cls=PlotlyJSONEncoder,allow_nan=False).replace("</","<\\/")
    return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><style>{CSS}</style><script>{plotly_js}</script></head><body>{content}<script type="application/json" id="report-data">{payload}</script><script>{RUNTIME}</script></body></html>'
